// current tree (what is on screen) vs workInProgress (next update)
const current = Array.from({ length: 800 }, (_, i) => 'row-' + i);
const next = current.slice();
// 12 rows genuinely change
for (const i of [3, 17, 42, 88, 120, 201, 333, 400, 555, 600, 712, 799]) {
  next[i] = 'row-' + i + '-CHANGED';
}

tasks.starter:
function propsChanged(prev, next) {
  return prev !== next;
}

